const { deepClone } = require('../../../src/options/clone');

describe('deepClone', () => {
  it('should return a deep clone of an array', () => {
    const input = [1, 2, { a: 3 }];
    const result = deepClone(input);
    expect(result).toEqual(input);
    expect(result).not.toBe(input);
    expect(result[2]).not.toBe(input[2]);
  });

  it('should return a deep clone of a plain object', () => {
    const input = { a: 1, b: { c: 2 } };
    const result = deepClone(input);
    expect(result).toEqual(input);
    expect(result).not.toBe(input);
    expect(result.b).not.toBe(input.b);
  });

  it('should return the same value for primitive types', () => {
    expect(deepClone(42)).toBe(42);
    expect(deepClone('hello')).toBe('hello');
    expect(deepClone(null)).toBe(null);
    expect(deepClone(undefined)).toBe(undefined);
    expect(deepClone(true)).toBe(true);
  });

  it('should handle empty arrays and objects', () => {
    expect(deepClone([])).toEqual([]);
    expect(deepClone({})).toEqual({});
  });

  it('should handle nested structures', () => {
    const input = { a: [1, { b: 2 }], c: { d: [3, 4] } };
    const result = deepClone(input);
    expect(result).toEqual(input);
    expect(result).not.toBe(input);
    expect(result.a).not.toBe(input.a);
    expect(result.a[1]).not.toBe(input.a[1]);
    expect(result.c).not.toBe(input.c);
    expect(result.c.d).not.toBe(input.c.d);
  });
});

