const validateSubclass = require('../../../src/subclass/validate').validateSubclass;

describe('validateSubclass', () => {
  let mockErrorClass;
  let mockParentClass;

  beforeEach(() => {
    global.classesData = new Set();
    mockParentClass = class ParentError {};
    mockErrorClass = class CustomError extends mockParentClass {};
  });

  afterEach(() => {
    delete global.classesData;
  });

  it.skip('should not throw an error if the class is already in classesData', () => {
    classesData.add(mockErrorClass); // Add the class to classesData
    expect(() => validateSubclass(mockErrorClass)).not.toThrow();
  });

  it('should throw an error if the class is not in classesData', () => {
    expect(() => validateSubclass(mockErrorClass)).toThrow(
      `"new CustomError()" must not be directly called.
This error class should be created like this instead:
  export const CustomError = ParentError.subclass('CustomError')`
    );
  });

  it('should correctly handle a class with a different parent class', () => {
    class AnotherParentError {}
    class AnotherCustomError extends AnotherParentError {}

    expect(() => validateSubclass(AnotherCustomError)).toThrow(
      `"new AnotherCustomError()" must not be directly called.
This error class should be created like this instead:
  export const AnotherCustomError = AnotherParentError.subclass('AnotherCustomError')`
    );
  });
});

