const { normalizeClassOpts } = require('../../../src/options/class');
const isPlainObj = require('is-plain-obj');

jest.mock('is-plain-obj', () => jest.fn());

describe('normalizeClassOpts', () => {
  const ParentError = class CustomError extends Error {};

  afterEach(() => {
    jest.clearAllMocks();
  });

  test('should return classOpts when it is a plain object', () => {
    const classOpts = { key: 'value' };
    isPlainObj.mockImplementation(() => true);

    const result = normalizeClassOpts(ParentError, classOpts);

    expect(isPlainObj).toHaveBeenCalledWith(classOpts);
    expect(result).toBe(classOpts);
  });

  test('should throw TypeError when classOpts is not a plain object', () => {
    const invalidClassOpts = 'not-an-object';
    isPlainObj.mockImplementation(() => false);

    expect(() => normalizeClassOpts(ParentError, invalidClassOpts)).toThrow(
      new TypeError(
        `The second argument of "CustomError.subclass()" must be a plain object, not: ${invalidClassOpts}`
      )
    );

    expect(isPlainObj).toHaveBeenCalledWith(invalidClassOpts);
  });

  test('should use default value for classOpts when not provided', () => {
    isPlainObj.mockImplementation(() => true);

    const result = normalizeClassOpts(ParentError);

    expect(isPlainObj).toHaveBeenCalledWith({});
    expect(result).toEqual({});
  });
});

